CREATE TABLE public.organization_onboarding_allowlist (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.organization_onboarding_allowlist TO service_role;
ALTER TABLE public.organization_onboarding_allowlist ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.enforce_organization_onboarding_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.platform_release_flags WHERE name='organization_onboarding' AND enabled) AND NOT public.is_platform_admin() AND NOT EXISTS(SELECT 1 FROM public.organization_onboarding_allowlist WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Organization onboarding awaits validation'; END IF; IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.slug IS DISTINCT FROM OLD.slug) THEN RAISE EXCEPTION 'Organization identity is immutable'; END IF; RETURN NEW; END $function$;